  (function (extra) {
    Object.keys(extra).forEach(function (k) {
      if (!Object.prototype.hasOwnProperty.call(A.ICONS, k)) A.ICONS[k] = '<svg class="icon icon--line" viewBox="0 0 24 24" aria-hidden="true" focusable="false">' + extra[k] + '</svg>';
    });
  })({
    search: '<circle class="duo" cx="11" cy="11" r="6.5"/><path d="m20 20-4.4-4.4"/>',
    sidebar: '<rect class="duo" x="3.5" y="4.5" width="17" height="15" rx="2.5"/><path d="M9.5 4.5v15"/>'
  });
  A.views = {};
  // the item editors, by kind (AdminContent, AdminItems, AdminPage): reopened after a reload
  A.editors = {};
  A.state = null;
  A.dirty = false;

  /*
   * Working together (the official admin page only): boot.js sets A.collab
   * to { lock(info, onStatus) → { release() }, where(area, view) }. In the
   * recovery admin it stays null and nothing below takes part.
   */
  A.collab = null;


  /* =======================================================
     DOM HELPERS
  ======================================================= */

  A.el = function (tag, attrs) {

    var node = document.createElement(tag);

    Object.keys(attrs || {}).forEach(function (name) {
      var value = attrs[name];
      if (value === null || value === undefined || value === false) return;
      if (name === 'class') node.className = value;
      else if (name === 'text') node.textContent = value;
      else if (name === 'value') node.value = value;
      else if (name === 'checked') node.checked = !!value;
      else if (name.indexOf('on') === 0 && typeof value === 'function') node.addEventListener(name.slice(2), value);
      // through the CSSOM, not the attribute: allowed under a strict CSP (no 'unsafe-inline')
      else if (name === 'style') node.style.cssText = String(value);
      else node.setAttribute(name, value === true ? '' : String(value));
    });

    for (var i = 2; i < arguments.length; i++) {
      appendChild(node, arguments[i]);
    }

    return node;

  };

  function appendChild(node, child) {

    if (child === null || child === undefined || child === false) return;
    if (Array.isArray(child)) { child.forEach(function (c) { appendChild(node, c); }); return; }
    node.appendChild(child instanceof Node ? child : document.createTextNode(String(child)));

  }

  var el = A.el;

  /* replaceChildren() that skips null/false (the DOM would print "null") */
  A.fill = function (node) {

    node.replaceChildren();
    for (var i = 1; i < arguments.length; i++) {
      appendChild(node, arguments[i]);
    }
    return node;

  };

