    var sections = A.byOrder(A.state.draft.sections).filter(function (s) { return !s.kind || s.kind === 'links'; });
    var defaultSection = sections.filter(function (s) { return s.key !== 'social'; })[0] || sections[0] || {};
    link = link || { enabled: true, featured: false, style: 'card', icon: 'link', section: defaultSection.key || '' };

    var featured = bool(link.featured);
    var box = A.errorBox();
    var limits = A.state.meta.limits;

    var title = A.counted('العنوان', link.title, limits.title, null, { required: true });
    var subtitle = A.counted('وصف قصير', link.subtitle, limits.subtitle, 'اختياري');
    var urlInput = A.textInput(link.url, { ltr: true, type: 'url', placeholder: 'https://', inputmode: 'url', required: true });

    var sectionSelect = el('select', { class: 'input', onchange: A.markDirty }, sections.map(function (s) {
      return el('option', { value: s.key, selected: s.key === link.section ? 'selected' : null, text: s.title + (bool(s.enabled) ? '' : ' (مخفي)') });
    }));
    var sectionField = A.field('القسم', sectionSelect);

    var style = A.choices('style', [
      { value: 'card', label: 'صف عريض' },
      { value: 'tile', label: 'مربع زي التطبيقات' }
    ], link.style === 'tile' ? 'tile' : 'card');
    var styleField = A.field('الشكل', style.node, 'المربع مناسب للسوشيال ميديا، والصف مناسب للينكات اللي محتاجة وصف');

    var cta = A.counted('نص الزرار', link.cta, limits.cta, 'مثلاً: ابعت دلوقتي');

