  A.editLink = editLink;
  A.editors.sections = editSection;
  A.editors.links = editLink;


  /* =======================================================
     PAGE LAYOUT — «ترتيب الصفحة»
  ======================================================= */

  var KIND_INFO = {
    meeting: { label: 'ركن الاجتماع', icon: 'church', titleHint: 'اسم القسم في لوحة التحكم (عنوان الكارت في الموقع هو اسم الاجتماع)', bannerHint: 'بيظهر فوق ركن الاجتماع (المعاد والموضوع)' },
    featured: { label: 'الروابط المميزة', icon: 'heart', bannerHint: 'بيظهر فوق الروابط المميزة (زي صوتك يهمنا)' },
    news: { label: 'الأخبار', icon: 'megaphone', publicTitle: true, titleHint: 'بيظهر فوق الأخبار في الموقع', bannerHint: 'بيظهر فوق الأخبار، وأي خبر من غير بوستر بياخده' },
    games: { label: 'التحديات والألعاب', icon: 'star', publicTitle: true, bannerHint: 'بيظهر فوق الألعاب، وأي لعبة من غير صورة بتاخده' },
    items: { label: 'مسابقات / فعاليات', icon: 'calendar', publicTitle: true, titleHint: 'بيظهر فوق القسم في الموقع', bannerHint: 'بيظهر فوق القسم، وأي عنصر جواه من غير بوستر بياخده' },
    location: { label: 'مكان الاجتماع', icon: 'map', bannerHint: 'بيظهر فوق كارت المكان والخريطة' },
    links: { label: 'مجموعة روابط', icon: 'link', publicTitle: true, titleHint: 'بيظهر فوق الروابط في الموقع', bannerHint: 'بيظهر فوق الروابط دي' },
    contacts: { label: 'تواصل مع الخدمة', icon: 'phone', bannerHint: 'بيظهر فوق كروت التواصل' },
    support: { label: 'الدعم الفني', icon: 'info', bannerHint: 'بيظهر فوق الدعم الفني' },
    share: { label: 'شارك الصفحة', icon: 'share', bannerHint: 'بيظهر فوق «شارك الصفحة»' }
  };

  A.KIND_INFO = KIND_INFO;

  /* how many things a section would show (0 = it stays hidden on the site) */
  function sectionCount(s) {

    var d = A.state.draft;
    var on = function (row) { return bool(row.enabled) && !bool(row.archived); };

    switch (s.kind) {
      case 'meeting': return A.setting('meeting.day') !== '' || (d.sessions || []).some(on) ? 1 : 0;
      case 'featured': return d.links.filter(function (l) { return bool(l.featured) && on(l); }).length;
      case 'news': return (d.news || []).filter(on).length;
      case 'games': return (d.games || []).filter(on).length;
      case 'items': return (d.activities || []).filter(function (a) {
        var type = (d.types || []).filter(function (t) { return t.key === a.type; })[0];
        return on(a) && type && type.section === s.key;
      }).length;
      case 'location': return A.setting('location.name') ? 1 : 0;
      case 'links': return d.links.filter(function (l) { return !bool(l.featured) && l.section === s.key && on(l); }).length;
      case 'contacts': return d.contacts.filter(function (c) { return c.kind !== 'support' && on(c); }).length;
      case 'support': return d.contacts.filter(function (c) { return c.kind === 'support' && on(c); }).length;
      default: return 1;
    }

  }

  A.sectionCount = sectionCount;

  function sectionLiveNow(s) {

    var v = A.visibility(bool(s.enabled), s.visibleFrom, s.visibleUntil);
    return (v.state === 'live' || v.state === 'always') && sectionCount(s) > 0;

  }

  /* Phase 8B (layout-sched.png): «ترتيب الصفحة» — one card, the sections in order: the grip (drag, or ↑ ↓ on
     it from the keyboard), the number, the name and when it shows («ظاهر على طول» / its schedule in words),
     ظاهر · بميعاد · مخفي, «الميعاد» (the section's editor) and its switch. What visitors see now: data-live. */
  A.views.layout = function () {

    var layout = A.state.layout || [];
    var upgraded = A.state.schema.data >= A.state.schema.target;
    var out = [];

    if (!upgraded) {
      out.push(A.upgradeNotice());
    }

    var list = el('ol', { class: 'p8-list layout-list p8-layout' }, layout.map(function (s, index) { return layoutItem(s, index, layout.length, upgraded); }));
    layoutDrag(list, layout);

    out.push(el('section', { class: 'card p8-card' },
      el('div', { class: 'p8-card__head' },
        el('span', { class: 'chipico', 'aria-hidden': 'true' }, icon('layers')),
        el('div', { class: 'p8-card__titles' },
          el('h2', { class: 'card__title', text: 'ترتيب الصفحة' }),
          el('p', { class: 'card__hint', text: 'أقسام الصفحة الرئيسية بالترتيب. كل قسم ممكن يتخبّى، أو يظهر ويختفي في ميعاد.' })),
        el('div', { class: 'p8-card__acts' },
          el('button', { class: 'btn btn--sm btn--ghost', type: 'button', onclick: function () { editSection(null); } }, icon('plus'), 'قسم روابط جديد'))),
      list,
      el('p', { class: 'p8-foot', text: 'الأقسام والترتيب بيبانوا في الموقع بعد «راجع وانشر»؛ المواعيد بتوقيت مصر.' })));

    return out;

  };

  /* a drop moves the section step by step (apiMoveSection), so the server keeps one rule for the order */
  function layoutDrag(list, layout) {

    var from = null;
    list.addEventListener('pointerdown', function (e) {
      var grip = e.target.closest('.grip');
      if (grip && !grip.closest('.item').classList.contains('is-locked')) grip.closest('.item').draggable = true;
    });
    list.addEventListener('dragstart', function (e) { from = e.target.closest('.item'); if (from) { from.classList.add('is-drag'); e.dataTransfer.effectAllowed = 'move'; } });
    list.addEventListener('dragover', function (e) {
      var over = e.target.closest('.item');
      if (!from || !over || over === from) return;
      e.preventDefault();
      var after = Array.prototype.indexOf.call(list.children, over) > Array.prototype.indexOf.call(list.children, from);
      list.insertBefore(from, after ? over.nextSibling : over);
    });
    list.addEventListener('dragend', function () {
      if (!from) return;
      var moved = from;
      moved.classList.remove('is-drag');
      moved.draggable = false;
      from = null;
      var key = moved.dataset.key;
      var before = layout.map(function (x) { return x.key; }).indexOf(key);
      var now = Array.prototype.indexOf.call(list.children, moved);
      var steps = now - before;
      if (!steps) return;
      var dir = steps > 0 ? 1 : -1;
      var chain = Promise.resolve();
      for (var i = 0; i < Math.abs(steps); i++) chain = chain.then(function () { return A.call('apiMoveSection', key, dir); });
      chain.then(function () { return A.call('apiState'); }).then(function (state) { A.applyState(state); A.toast('الترتيب اتحفظ — بيبان بعد «راجع وانشر»'); })
        .catch(function (error) { A.fail(error); A.render(); });
    });

  }

  function layoutItem(s, index, total, upgraded) {

    var info = KIND_INFO[s.kind] || KIND_INFO.links;
    var count = sectionCount(s);
    var enabled = bool(s.enabled);
    var locked = s.virtual;
    var v = A.visibility(enabled, s.visibleFrom, s.visibleUntil);
    var timed = !!(s.visibleFrom || s.visibleUntil);
    var empty = enabled && count === 0;
    var when = timed
      ? [s.visibleFrom ? 'يظهر من ' + A.formatWall(s.visibleFrom) : '', s.visibleUntil ? 'يختفي ' + A.formatWall(s.visibleUntil) : ''].filter(Boolean).join(' · ')
      : enabled ? 'ظاهر على طول' : 'مخفي';
    var state = el('span', { class: 'p8-tag chip--state' + (empty ? '' : !enabled ? '' : v.state === 'live' && !timed ? ' p8-tag--ok' : timed ? ' p8-tag--info' : ' p8-tag--ok'), 'data-state': v.state },
      timed && enabled && !empty ? icon('clock') : null,
      empty ? 'فاضي — مش هيظهر' : !enabled ? 'مخفي' : timed ? 'بميعاد' : 'ظاهر');

    var toggle = A.switchInput('ظاهر', enabled, function (checked) {
      A.dirty = false;
      // shown at once; the server's answer (or its refusal) follows (A.draftChange)
      A.draftChange({
        apply: function (state) { A.sectionEnabledLocally(state, s.key, checked); },
        run: function () { return A.call('apiSetSectionEnabled', s.key, checked); },
        done: function () { A.toast(checked ? 'القسم هيظهر بعد النشر' : 'القسم هيختفي بعد النشر'); }
      });
    });
    toggle.input.disabled = locked;
    toggle.node.classList.add('p8-switch');

    var grip = el('button', { class: 'grip', type: 'button', 'aria-label': 'رتّب «' + s.title + '» (الأسهم لفوق ولتحت)', disabled: locked || null, onkeydown: function (e) {
      if (e.key === 'ArrowUp' && index > 0) { e.preventDefault(); A.move('apiMoveSection', s.key, -1, e.currentTarget); }
      if (e.key === 'ArrowDown' && index < total - 1) { e.preventDefault(); A.move('apiMoveSection', s.key, 1, e.currentTarget); }
    } }, icon('grip'));

    var more = s.kind === 'links' && !locked ? el('button', { class: 'p8-iconbtn', type: 'button', 'aria-haspopup': 'menu', 'aria-expanded': 'false', 'aria-label': 'اختيارات تانية: ' + s.title, onclick: function (e) {
      var button = e.currentTarget;
      var del = A.menuItem('trash', 'امسح القسم', function () { removeSection(s, button); }, { danger: true });
      del.setAttribute('aria-label', 'مسح ' + s.title);
      A.menu(button, 'menu--p8', [del], { align: 'start' });
    } }, icon('dots')) : null;

    return el('li', { class: 'p8-item item' + (enabled ? '' : ' item--off') + (locked ? ' is-locked' : ''), 'data-key': s.key, 'data-live': sectionLiveNow(s) ? '1' : null },
      grip,
      el('span', { class: 'stage__n', 'aria-hidden': 'true', text: A.digits(index + 1) }),
      el('div', { class: 'p8-item__main' },
        el('b', { class: 'p8-item__line' }, el('span', { class: 'item__title', text: s.title || info.label })),
        el('small', { text: when + (s.kind === 'links' ? ' · ' + s.key : '') })),
      el('div', { class: 'p8-item__acts' },
        state,
        locked ? null : el('button', { class: 'btn btn--sm', type: 'button', 'aria-label': 'تعديل ' + s.title, onclick: function () { editSection(s); } }, icon('clock'), 'الميعاد'),
        more,
        toggle.node));

  }


  /* =======================================================
     LOCATION
  ======================================================= */

  A.views.location = function () {

    var setting = A.setting;
    var limits = A.state.meta.limits;
    var box = A.errorBox();

    var name = A.counted('اسم المكان', setting('location.name'), limits.title, 'لو فاضي كارت المكان مش هيظهر');
    var address = A.counted('العنوان', setting('location.address'), limits.address);
    var note = A.counted('ملاحظة', setting('location.note'), limits.note, 'مثلاً: القاعة اللي في الدور التاني');
    var mapsUrl = A.textInput(setting('location.mapsUrl'), { ltr: true, type: 'url', placeholder: 'https://maps.app.goo.gl/...' });
    var lat = A.textInput(setting('location.lat'), { ltr: true, inputmode: 'decimal', placeholder: '26.73' });
    var lng = A.textInput(setting('location.lng'), { ltr: true, inputmode: 'decimal', placeholder: '33.93' });

    var resolve = el('button', { class: 'btn', type: 'button' }, icon('map'), 'هات الإحداثيات من اللينك');

    resolve.addEventListener('click', function () {
      box.hidden = true;
      A.withBusy(resolve, A.call('apiResolveMapsUrl', mapsUrl.value.trim()))
        .then(function (coords) {
          lat.value = coords.lat;
          lng.value = coords.lng;
          A.markDirty();
          A.toast('اتجابت الإحداثيات — دوس حفظ');
        })
        .catch(function (error) { A.fail(error, box); });
    });

    return [A.card('مكان الاجتماع', 'زرار "الاتجاهات" والخريطة بيستخدموا الإحداثيات.',
      box,
      el('div', { class: 'form' },
        name.node,
        address.node,
        note.node,
        A.field('لينك جوجل ماب', mapsUrl),
        el('div', { class: 'actions' }, resolve),
        el('div', { class: 'row' }, A.field('خط العرض', lat), A.field('خط الطول', lng))
      ),
      A.settingsSaver(function () {
        return {
          'location.name': name.input.value,
          'location.address': address.input.value,
          'location.note': note.input.value,
          'location.mapsUrl': mapsUrl.value.trim(),
          'location.lat': lat.value.trim(),
          'location.lng': lng.value.trim()
        };
      }, box)
    )];

  };


  /* =======================================================
     CONTACTS
  ======================================================= */

  A.views.contacts = function () {

    var contacts = A.byOrder(A.state.draft.contacts);

    return [A.card('التواصل', '"تواصل مع الخدمة" بيظهر بشكل واضح، و"الدعم الفني" بيظهر أهدى.',
      el('div', { class: 'actions' },
        el('button', { class: 'btn btn--primary', type: 'button', onclick: function () { editContact(null); } }, '+ جهة تواصل')
      ),
      contacts.length
        ? el('ul', { class: 'list' }, contacts.map(function (contact, index) {
          var enabled = bool(contact.enabled);
          return A.listItem({
            icon: contact.method === 'whatsapp' ? 'whatsapp' : 'phone',
            title: contact.name,
            sub: contact.phone,
            off: !enabled,
            chips: [
              A.chip(contact.kind === 'support' ? 'دعم فني' : 'تواصل مع الخدمة', 'gold'),
              A.chip(contact.method === 'whatsapp' ? 'واتساب بس' : 'اتصال بس'),
              contact.role ? A.chip(contact.role) : null,
              A.visibilityChip(enabled)
            ],
            controls: [
              el('span', { class: 'spacer' }),
              el('button', { class: 'icon-btn', type: 'button', 'aria-label': 'لفوق', disabled: index === 0, onclick: function (e) { A.move('apiMoveContact', contact.id, -1, e.currentTarget); } }, icon('chevron-up')),
              el('button', { class: 'icon-btn', type: 'button', 'aria-label': 'لتحت', disabled: index === contacts.length - 1, onclick: function (e) { A.move('apiMoveContact', contact.id, 1, e.currentTarget); } }, icon('chevron')),
              A.editButton(contact.name, function () { editContact(contact); }),
              A.deleteButton(contact.name, function (e) {
                var button = e.currentTarget;
                A.confirmDelete(contact.name).then(function (ok) {
                  if (!ok) return;
                  A.withBusy(button, A.call('apiDeleteContact', contact.id))
                    .then(function (next) { A.applyState(next); A.toast('اتمسح — هيختفي من الموقع بعد النشر'); })
                    .catch(function (error) { A.fail(error); });
                });
              })
            ]
          });
        }))
        : el('p', { class: 'empty', text: 'مفيش جهات تواصل' })
    )];

  };

  /* what the site shows when these are left empty (placeholders here) */
  var CONTACT_DEFAULTS = {
    serviceIntro: 'عندك سؤال أو محتاج تتكلم؟',
    supportIntro: 'معايا مشكلة',
    reply: 'أهلاً بيك 👋 ابعتلي المشكلة أو التفاصيل وأنا هساعدك إن شاء الله.'
  };

  function editContact(contact) {

    var isNew = !contact;
    contact = contact || { enabled: true, kind: 'service', method: 'call' };

    var limits = A.state.meta.limits;
    var box = A.errorBox();
    var name = A.counted('الاسم', contact.name, limits.personName, null, { required: true });
    var role = A.counted('الدور', contact.role, limits.role, 'مثلاً: أمين الخدمة');
    var description = A.counted('وصف قصير', contact.description, limits.description);
    var phoneInput = A.textInput(contact.phone, { ltr: true, type: 'tel', inputmode: 'tel', placeholder: '01xxxxxxxxx' });

    var kind = A.choices('kind', [
      { value: 'service', label: 'تواصل مع الخدمة' },
      { value: 'support', label: 'دعم فني (أهدى)' }
    ], contact.kind || 'service', function (value) { syncKind(value); });

    var message = A.counted('رسالة الواتساب الجاهزة', contact.message, limits.message, 'اختياري — بتتكتب لوحدها لما حد يفتح الواتساب', { multiline: true });

    var method = A.choices('method', [
      { value: 'call', label: 'اتصال بس', icon: 'phone' },
      { value: 'whatsapp', label: 'واتساب بس', icon: 'whatsapp' }
    ], contact.method || 'call', function (value) { message.node.hidden = value !== 'whatsapp'; });

    message.node.hidden = (contact.method || 'call') !== 'whatsapp';

    // the person card (schema 4): a photo, the opening line, the reply bubble
    var avatar = A.imagePicker(contact.image || '', {
      label: 'الصورة (اختياري)',
      className: 'picker--avatar',
      hint: 'صورة الشخص في الكارت — من المكتبة أو ارفع جديدة. من غيرها بيظهر أول حرف من الاسم'
    });
    var intro = A.counted('جملة البداية', contact.intro, limits.contactIntro || 80, ' ', {});
    var reply = A.counted('الرد', contact.reply, limits.contactReply || 200, 'الرد اللي بيظهر في الكارت بعد جملة البداية (للدعم الفني بس)', { multiline: true, rows: 3, placeholder: CONTACT_DEFAULTS.reply });

    function syncKind(value) {
      var support = value === 'support';
      intro.input.placeholder = CONTACT_DEFAULTS[support ? 'supportIntro' : 'serviceIntro'];
      intro.node.querySelector('.field__hint').textContent = support
        ? 'اللي الزائر بيقوله في الكارت (فقاعة منه). سيبه فاضي للجملة اللي ظاهرة'
        : 'سطر دعوة صغير فوق زرار التواصل. سيبه فاضي للجملة اللي ظاهرة';
      reply.node.hidden = !support;
    }

    var enabled = A.switchInput('ظاهر', contact.enabled === undefined ? true : bool(contact.enabled));
    var save = el('button', { class: 'btn btn--primary', type: 'button', text: isNew ? 'إضافة' : 'حفظ' });

    save.addEventListener('click', function () {
      if (avatar.busy()) {
        A.toast('الصورة لسه بتترفع — استنى «تم الرفع ✓» وبعدين احفظ', 'info');
        return;
      }
      box.hidden = true;
      var isSupport = kind.value() === 'support';
      A.withBusy(save, A.call('apiSaveContact', {
        id: contact.id || '',
        name: name.input.value,
        role: role.input.value,
        description: description.input.value,
        phone: phoneInput.value,
        kind: kind.value(),
        method: method.value(),
        message: message.input.value,
        image: avatar.value(),
        intro: intro.input.value,
        // the reply belongs to the support card; a service card keeps none
        reply: isSupport ? reply.input.value : '',
        enabled: enabled.input.checked
      }))
        .then(function (next) {
          A.dirty = false;
          document.getElementById('sheet').close();
          A.applyState(next);
          A.toast('اتحفظ ✓ — لسه محتاج نشر');
        })
        .catch(function (error) { A.fail(error, box); });
    });

    A.dirty = false;

    A.openSheet(isNew ? 'جهة تواصل جديدة' : 'تعديل: ' + contact.name, [
      box,
      el('div', { class: 'form' },
        name.node,
        role.node,
        description.node,
        A.field('رقم التليفون', phoneInput),
        A.field('النوع', kind.node),
        A.field('طريقة التواصل', method.node),
        message.node,
        el('div', { class: 'form-group' },
          el('p', { class: 'section-label', text: 'الكارت في الموقع' }),
          avatar.node,
          intro.node,
          reply.node
        ),
        enabled.node
      )
    ], A.sheetFooter(save), {
      // one editor per item: the official admin locks it while this is open
      draft: A.draftKey('contacts', isNew ? '' : contact.id),
      lock: isNew ? null : A.editLock('contacts', contact.id, 'جهة تواصل «' + (contact.name || '') + '»', function () { var fresh = A.findRow(A.state.draft.contacts, 'id', contact.id); if (fresh) editContact(fresh); else A.closeSheet(); })
    });

    // the chosen kind (a draft that came back after a reload may have changed it)
    syncKind(kind.value() || 'service');

  }

  A.editContact = editContact;
  A.editors.contacts = editContact;


