    A.fill(save, icon('check'), el('span', { text: isNew ? 'إضافة' : 'احفظ' }));
    var prevImg = el('img', { alt: '', hidden: true });
    var prevTitle = el('b');
    var prevBadge = el('span', { class: 'p8-tag p8-tag--warn' });
