    var whole = Math.floor(value);
    var tenth = Math.round((value - whole) * 10);
    var h = Math.floor(whole / 3600);
    var m = Math.floor((whole % 3600) / 60);
    var s = whole % 60;
    var two = function (n) { return (n < 10 ? '0' : '') + n; };

