          var words = { approved: 'الطلب جاهز للاستلام ✓', fulfilled: 'اتسلمت ✓', cancelled: 'اتلغى ✓ — ' + ar(rd.cost) + ' نقطة رجعت، الرصيد دلوقتي ' + ar(r.balance) };
          A.toast(r.changed === false ? 'الطلب كان كده بالفعل' : words[status]);
