      sub: isNew ? 'صفحة خدمة · بتتحفظ مسودة لحد النشر' : ['/' + page.slug + '/', page.archived ? 'في الأرشيف' : page.live ? 'منشورة' : 'لسه متنشرتش', page.partner ? 'بإشراف B.U.G' : ''].filter(Boolean).join(' · '),
      next: false,
